 private void initPlayer(){LivePlaybackSession.RetryResolver resolver=managedBackend?item->managedSource.resolve(getIntent().getStringExtra("server_name"),item,true):serverTen?item->refreshServerTen(item):(builtIn||p==null?null:item->engine.resolveLiveStream(p,item));playbackSession=new LivePlaybackSession(this,playerView,resolver,new LivePlaybackSession.Listener(){public void onBuffering(boolean buffering){loading.setVisibility(buffering?View.VISIBLE:View.GONE);}public void onReady(){loading.setVisibility(View.GONE);}public void onFatalPlaybackError(String message){loading.setVisibility(View.GONE);Toast.makeText(LiveTvActivity.this,message,Toast.LENGTH_LONG).show();}});}
 private boolean isStalkerPlaylist(){return !serverTen&&!managedBackend&&!builtIn&&p!=null&&p.getType()==PlaylistType.STALKER_PORTAL;}
 private String stalkerError(Exception e){int code=ProviderPlaybackPolicy.status(e);if(code>0)return "Stalker: "+ProviderPlaybackPolicy.message(code);String message=e.getMessage();if(message!=null&&message.toLowerCase(Locale.ROOT).contains("unauthorized"))return "Stalker: session-i u refuzua edhe pas rifreskimit.";return "Stalker: nuk u mor URL e vlefshme për kanalin.";}
