 private List<String> countryLabels(){List<String>x=new ArrayList<>();for(CountryGroup g:countries){int n=0;for(Category z:g.categories)n+=liveCounts.getOrDefault(z.id,0);x.add(g.label+"  ("+n+")");}return x;}
 private List<String> categoryLabels(){List<String>x=new ArrayList<>();for(Category c:categories)x.add(CountryResolver.categoryLabel(c.name)+"  ("+liveCounts.getOrDefault(c.id,0)+")");return x;}
 private void selectCountry(int pos){if(pos<0||pos>=countries.size())return;if(country!=null&&countries.get(pos).key.equals(country.key)&&categoriesView.getAdapter()!=null)return;country=countries.get(pos);categories=new ArrayList<>(country.categories);List<String>x=categoryLabels();categoriesView.setAdapter(adapter(x));overlayCategories.setAdapter(adapter(x));channels=Collections.emptyList();shown=new ArrayList<>();channelsView.setAdapter(channelAdapter());overlayChannels.setAdapter(channelAdapter());if(!x.isEmpty()){categoriesView.setSelection(0);selectCategory(0,false);}}
 private void selectCategory(int pos,boolean fromOverlay){if(pos<0||pos>=categories.size())return;category=categories.get(pos);channels=liveItems.getOrDefault(category.id,Collections.emptyList());filter("");if(fromOverlay){overlayChannels.requestFocus();if(!shown.isEmpty())overlayChannels.setSelection(0);}else{channelsView.requestFocus();if(!shown.isEmpty())channelsView.setSelection(0);}}
 private int currentShownIndex(){if(current==null)return -1;for(int n=0;n<shown.size();n++){StreamItem i=shown.get(n);if(i!=null&&current.id.equals(i.id))return n;}return -1;}
 private void syncCurrentChannelPosition(){int n=currentShownIndex();if(n<0)return;currentIndex=n;channelsView.setSelection(n);overlayChannels.setSelection(n);}
 private void filter(String q){q=q==null?"":q.trim().toLowerCase(Locale.ROOT);shown=new ArrayList<>();for(StreamItem i:channels)if(q.isEmpty()||(i.name!=null&&i.name.toLowerCase(Locale.ROOT).contains(q)))shown.add(i);channelsView.setAdapter(channelAdapter());overlayChannels.setAdapter(channelAdapter());syncCurrentChannelPosition();}
 private void activateChannel(int pos,boolean fromOverlay){if(pos<0||pos>=shown.size())return;StreamItem item=shown.get(pos);if(current!=null&&current.id.equals(item.id)&&playbackSession!=null&&playbackSession.isActive()){syncCurrentChannelPosition();if(fromOverlay)hideOverlay();return;}play(pos,fromOverlay);}
 private void play(int pos,boolean fromOverlay){if(pos<0||pos>=shown.size())return;playChannel(shown.get(pos),fromOverlay);}
 private void playChannel(StreamItem item,boolean fromOverlay){final long generation=++playbackGeneration;playbackSession.beginSelection();loading.setVisibility(View.VISIBLE);worker.execute(()->{try{ResolvedStream r=managedBackend?managedSource.resolve(getIntent().getStringExtra("server_name"),item,false):serverTen?refreshServerTen(item):(builtIn?direct(item):engine.resolveLiveStream(p,item));runOnUiThread(()->{if(generation!=playbackGeneration||isFinishing()||isDestroyed())return;playResolved(item,r);if(fromOverlay)hideOverlay();});}catch(Exception e){runOnUiThread(()->{if(generation!=playbackGeneration||isFinishing()||isDestroyed())return;loading.setVisibility(View.GONE);Toast.makeText(this,isStalkerPlaylist()?stalkerError(e):LiveErrorSummary.connection(e),Toast.LENGTH_LONG).show();});}});}
 private void playResolved(StreamItem item,ResolvedStream r){idle.setVisibility(View.GONE);current=item;currentIndex=shown.indexOf(item);try{resolvedHost=new java.net.URL(r.url).getHost();}catch(Exception ignored){resolvedHost="n/a";}playbackSession.play(item,r);title.setText(item.name);activeSchedule=schedules.getOrDefault(sourceId()+"|"+item.id,EpgSchedule.empty());epgLoading=false;lastEpgRequest=0;renderEpg();loadEpg(item,playbackGeneration);((Button)findViewById(R.id.live_favorite)).setText(favorites.contains(sourceId(),item)?"★ Favorite":"☆ Favorite");syncCurrentChannelPosition();channelsView.invalidateViews();overlayChannels.invalidateViews();}
