 private android.widget.BaseAdapter channelAdapter(){return new android.widget.BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int n){return shown.get(n);}public long getItemId(int n){return n;}public View getView(int n,View v,android.view.ViewGroup parent){LinearLayout row=v instanceof LinearLayout?(LinearLayout)v:new LinearLayout(LiveTvActivity.this);row.removeAllViews();row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(8,6,8,6);row.setMinimumHeight((int)(52*getResources().getDisplayMetrics().density));row.setBackgroundResource(R.drawable.bg_live_row);ImageView logo=new ImageView(LiveTvActivity.this);int sz=(int)(38*getResources().getDisplayMetrics().density);row.addView(logo,new LinearLayout.LayoutParams(sz,sz));TextView t=new TextView(LiveTvActivity.this);StreamItem i=shown.get(n);t.setText(i.name==null?"":i.name);t.setTextColor(android.graphics.Color.WHITE);t.setTextSize(14);t.setSingleLine(true);t.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1);tp.leftMargin=8;LinearLayout textColumn=new LinearLayout(LiveTvActivity.this);textColumn.setOrientation(1);textColumn.addView(t);EpgSchedule schedule=schedules.get(sourceId()+"|"+i.id);EpgSchedule.Program program=schedule==null?null:schedule.active(System.currentTimeMillis());
if(program!=null){TextView programText=new TextView(LiveTvActivity.this);programText.setText(program.label());programText.setTextColor(android.graphics.Color.rgb(170,198,219));programText.setTextSize(11);programText.setSingleLine(true);programText.setEllipsize(android.text.TextUtils.TruncateAt.END);textColumn.addView(programText);if(program.timed()){ProgressBar progress=new ProgressBar(LiveTvActivity.this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgress(program.progress(System.currentTimeMillis()));textColumn.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));}}
row.addView(textColumn,tp);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);if(i.logo!=null&&!i.logo.trim().isEmpty())loadLogo(logo,i.logo);else{String fallback=logoFallback(i);if(fallback!=null)loadLogo(logo,fallback);else logo.setImageResource(R.drawable.lazytv_official_logo);}row.setActivated(current!=null&&current.id.equals(i.id));return row;}};}
 private String logoFallback(StreamItem i){if(i==null||i.tvgId==null||i.tvgId.trim().isEmpty())return null;String id=i.tvgId.trim();return"https://logo.dvbdata.com/"+java.net.URLEncoder.encode(id)+".png";}
 private void loadLogo(ImageView v,String url){final long epoch=viewGeneration;v.setTag(url);v.setImageResource(R.drawable.lazytv_official_logo);imageWorker.execute(()->{java.net.HttpURLConnection cn=null;try{cn=(java.net.HttpURLConnection)new java.net.URL(url).openConnection();cn.setInstanceFollowRedirects(true);cn.setRequestProperty("User-Agent","Mozilla/5.0 LazyTV-PRO");cn.setRequestProperty("Accept","image/*,*/*;q=0.8");cn.setConnectTimeout(6000);cn.setReadTimeout(8000);android.graphics.Bitmap b=android.graphics.BitmapFactory.decodeStream(cn.getInputStream());if(b!=null)runOnUiThread(()->{if(epoch==viewGeneration&&!isDestroyed()&&url.equals(v.getTag()))v.setImageBitmap(b);});}catch(Exception ignored){runOnUiThread(()->{if(epoch==viewGeneration&&!isDestroyed()&&url.equals(v.getTag()))v.setImageResource(R.drawable.lazytv_official_logo);});}finally{if(cn!=null)cn.disconnect();}});}
 private void buildControls(){
  FrameLayout frame=(FrameLayout)root.getParent();fullControls=new LinearLayout(this);fullControls.setOrientation(1);fullControls.setPadding(dp(10),dp(7),dp(10),dp(8));fullControls.setBackgroundColor(android.graphics.Color.argb(225,4,15,28));
  fullNow=new TextView(this);fullNow.setTextColor(android.graphics.Color.WHITE);fullNow.setTextSize(14);fullNow.setMaxLines(2);fullControls.addView(fullNow);
  fullProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);fullProgress.setMax(100);fullControls.addView(fullProgress,new LinearLayout.LayoutParams(-1,dp(4)));
  fullNext=new TextView(this);fullNext.setTextColor(android.graphics.Color.rgb(170,198,219));fullNext.setTextSize(12);fullNext.setMaxLines(2);fullControls.addView(fullNext);
  LinearLayout actions=new LinearLayout(this);actions.setOrientation(0);fullControls.addView(actions);
  Button[] buttons=new Button[6];String[] labels={"CH−","CH+","☆ Favorite","EPG","Lista","Back"};
  for(int n=0;n<buttons.length;n++){Button button=new Button(this);button.setId(View.generateViewId());button.setText(labels[n]);button.setAllCaps(false);button.setTextColor(android.graphics.Color.WHITE);button.setTextSize(isLandscapeLayout()?13:10);button.setBackgroundResource(R.drawable.bg_player_button);button.setPadding(dp(3),0,dp(3),0);button.setFocusable(true);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,dp(46),n==2?1.6f:1);params.setMargins(dp(2),dp(4),dp(2),0);actions.addView(button,params);buttons[n]=button;}
  for(int n=0;n<buttons.length;n++){buttons[n].setNextFocusLeftId(buttons[(n+buttons.length-1)%buttons.length].getId());buttons[n].setNextFocusRightId(buttons[(n+1)%buttons.length].getId());buttons[n].setNextFocusUpId(R.id.live_player);}
  fullPrevious=buttons[0];fullFavorite=buttons[2];buttons[0].setOnClickListener(v->playAdjacent(-1));buttons[1].setOnClickListener(v->playAdjacent(1));buttons[2].setOnClickListener(v->toggleFavorite());buttons[3].setOnClickListener(v->showEpg());buttons[4].setOnClickListener(v->showOverlay());buttons[5].setOnClickListener(v->onBackPressed());
  FrameLayout.LayoutParams layout=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);frame.addView(fullControls,layout);fullControls.setVisibility(View.GONE);
 }
 private void toggleFavorite(){if(current==null)return;boolean favorite=favorites.toggle(sourceId(),current);((Button)findViewById(R.id.live_favorite)).setText(favorite?"★ Favorite":"☆ Favorite");if(fullFavorite!=null)fullFavorite.setText(favorite?"★ Favorite":"☆ Favorite");}
 private void loadEpg(StreamItem item,long generation){
  if(item==null||epgLoading)return;epgLoading=true;lastEpgRequest=System.currentTimeMillis();final String provider=sourceId();final Playlist selectedPlaylist=p;
  epgWorker.execute(()->{EpgSchedule result;try{result=engine.loadLiveSchedule(selectedPlaylist,item);}catch(Exception unavailable){result=EpgSchedule.empty();}final EpgSchedule schedule=result;
   runOnUiThread(()->{if(generation!=playbackGeneration||isFinishing()||isDestroyed()||current==null||!item.id.equals(current.id)||!provider.equals(sourceId()))return;epgLoading=false;activeSchedule=schedule;schedules.put(provider+"|"+item.id,schedule);renderEpg();channelsView.invalidateViews();});
  });
 }
 private void renderEpg(){long now=System.currentTimeMillis();EpgSchedule.Program program=activeSchedule.active(now),next=activeSchedule.upcoming(now);
  String currentText=program==null?"EPG nuk disponohet":"TANI: "+program.label(),nextText=next==null?"":"MË PAS: "+next.label();epg.setText(currentText+(nextText.isEmpty()?"":"\n"+nextText));
  if(fullNow!=null){fullNow.setText((current==null?"":current.name+" • ")+currentText);fullNext.setText(nextText);fullProgress.setVisibility(program!=null&&program.timed()?View.VISIBLE:View.GONE);if(program!=null)fullProgress.setProgress(program.progress(now));if(current!=null)fullFavorite.setText(favorites.contains(sourceId(),current)?"★ Favorite":"☆ Favorite");}
 }
 private void showEpg(){long now=System.currentTimeMillis();EpgSchedule.Program program=activeSchedule.active(now),next=activeSchedule.upcoming(now);
  String text=program==null?"EPG nuk disponohet":"TANI\n"+program.label()+(program.description.isEmpty()?"":"\n"+program.description);
  if(next!=null)text+="\n\nMË PAS\n"+next.label()+(next.description.isEmpty()?"":"\n"+next.description);
  new AlertDialog.Builder(this).setTitle(current==null?"EPG":current.name).setMessage(text).setPositiveButton("Mbyll",null).show();
 }
 private boolean isLandscapeLayout(){return getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE;}
 private void setFullscreen(boolean on){displayState.fullscreen(on);renderFullscreen(on);}
 private void renderFullscreen(boolean on){fullscreen=on;if(fullControls!=null)fullControls.setVisibility(on&&displayState.controls()?View.VISIBLE:View.GONE);View column=findViewById(R.id.live_player_column);boolean landscape=isLandscapeLayout();LinearLayout.LayoutParams cp=(LinearLayout.LayoutParams)column.getLayoutParams();if(on){topBar.setVisibility(View.GONE);bottomBar.setVisibility(landscape?View.GONE:View.VISIBLE);leftPanel.setVisibility(View.GONE);channelPanel.setVisibility(View.GONE);info.setVisibility(View.GONE);if(!landscape)contentRow.setVisibility(View.GONE);else contentRow.setVisibility(View.VISIBLE);contentRow.setPadding(0,0,0,0);root.setPadding(0,0,0,0);cp.width=ViewGroup.LayoutParams.MATCH_PARENT;cp.height=ViewGroup.LayoutParams.MATCH_PARENT;cp.weight=0;cp.setMargins(0,0,0,0);column.setLayoutParams(cp);playerView.setResizeMode(androidx.media3.ui.AspectRatioFrameLayout.RESIZE_MODE_FIT);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);hideOverlay();playerView.requestFocus();}else{getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_VISIBLE);root.setPadding(dp(10),dp(8),dp(10),dp(8));topBar.setVisibility(View.VISIBLE);bottomBar.setVisibility(View.VISIBLE);leftPanel.setVisibility(View.VISIBLE);channelPanel.setVisibility(View.VISIBLE);info.setVisibility(View.VISIBLE);contentRow.setVisibility(View.VISIBLE);contentRow.setPadding(0,dp(8),0,dp(8));cp.height=ViewGroup.LayoutParams.MATCH_PARENT;if(landscape){cp.width=0;cp.weight=60f;cp.setMargins(dp(8),0,0,0);}else{cp.width=ViewGroup.LayoutParams.MATCH_PARENT;cp.weight=0;cp.height=0;cp.weight=1f;cp.setMargins(0,dp(8),0,0);}column.setLayoutParams(cp);playerView.setResizeMode(androidx.media3.ui.AspectRatioFrameLayout.RESIZE_MODE_FIT);hideOverlay();syncCurrentChannelPosition();}}
 private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
 private void showOverlay(){if(!displayState.openBrowser())return;renderFullscreen(false);overlay.setVisibility(View.GONE);syncCurrentChannelPosition();channelsView.requestFocus();}
 private void hideOverlay(){overlayOpen=false;overlay.setVisibility(View.GONE);playerView.requestFocus();}
 private void toggleControls(){if(displayState.controls()){displayState.hideControls();fullControls.setVisibility(View.GONE);playerView.requestFocus();}else if(displayState.showControls()){renderEpg();fullControls.setVisibility(View.VISIBLE);fullControls.bringToFront();fullPrevious.requestFocus();}}
 private void toggleOverlay(){if(displayState.closeBrowser()){renderFullscreen(true);return;}if(fullscreen)showOverlay();}
 private void playAdjacent(int delta){List<StreamItem> context=shown;if(current!=null&&currentShownIndex()<0)context=liveItems.getOrDefault(current.categoryId,shown);StreamItem next=LiveChannelNavigator.adjacent(context,current==null?null:current.id,delta);if(next!=null)playChannel(next,false);}
 private void openCatalogType(String type){if(managedBackend){Intent managed=new Intent(this,ManagedCatalogActivity.class);managed.putExtra("server_name",getIntent().getStringExtra("server_name"));managed.putExtra("catalog_type",type);startActivity(managed);return;}if(serverTen){Toast.makeText(this,"Server 10 aktualisht ofron LIVE.",Toast.LENGTH_SHORT).show();return;}if(p==null){Toast.makeText(this,type+" kërkon provider me katalog",Toast.LENGTH_SHORT).show();return;}Intent i=new Intent(this,de.lazytv.pro.catalog.CatalogActivity.class);i.putExtra("playlist_id",p.getId());i.putExtra(de.lazytv.pro.catalog.CatalogActivity.EXTRA_TYPE,type);startActivity(i);}
 @Override public boolean dispatchKeyEvent(android.view.KeyEvent event){
  if(event.getAction()!=android.view.KeyEvent.ACTION_DOWN)return super.dispatchKeyEvent(event);int key=event.getKeyCode();
  if(fullscreen&&(key==android.view.KeyEvent.KEYCODE_DPAD_CENTER||key==android.view.KeyEvent.KEYCODE_ENTER)&&!displayState.controls()){toggleControls();return true;}
  if(fullscreen&&key==android.view.KeyEvent.KEYCODE_MENU){showOverlay();return true;}
  if(!fullscreen&&(key==android.view.KeyEvent.KEYCODE_DPAD_CENTER||key==android.view.KeyEvent.KEYCODE_ENTER)&&playerView.hasFocus()&&current!=null){setFullscreen(true);return true;}
  return super.dispatchKeyEvent(event);
 }
 @Override public void onBackPressed(){if(displayState.closeBrowser()){renderFullscreen(true);return;}if(displayState.hideControls()){fullControls.setVisibility(View.GONE);playerView.requestFocus();return;}if(fullscreen){setFullscreen(false);return;}super.onBackPressed();}
 @Override public void onConfigurationChanged(Configuration configuration){
  super.onConfigurationChanged(configuration);if(playerView==null)return;
  PlayerView retained=playerView;String selectedCountry=country==null?"":country.key,selectedCategory=category==null?"":category.id;
  String query=search.getText().toString(),program=epg.getText().toString();int channelPosition=channelsView.getFirstVisiblePosition();
  ViewGroup oldParent=(ViewGroup)retained.getParent();if(oldParent!=null)oldParent.removeView(retained);
  setContentView(R.layout.activity_live_tv);PlayerView placeholder=findViewById(R.id.live_player);ViewGroup frame=(ViewGroup)placeholder.getParent();
  ViewGroup.LayoutParams params=placeholder.getLayoutParams();int index=frame.indexOfChild(placeholder);frame.removeView(placeholder);frame.addView(retained,index,params);
  bind();countrySpinner.setAdapter(spinnerAdapter(countryLabels()));int countryIndex=0;
  for(int n=0;n<countries.size();n++)if(countries.get(n).key.equals(selectedCountry)){countryIndex=n;break;}
  countrySpinner.setSelection(countryIndex);selectCountry(countryIndex);
  for(int n=0;n<categories.size();n++)if(categories.get(n).id.equals(selectedCategory)){selectCategory(n,false);break;}
  search.setText(query);channelsView.setSelection(channelPosition);
  if(current!=null){title.setText(current.name);epg.setText(program);idle.setVisibility(View.GONE);((Button)findViewById(R.id.live_favorite)).setText(favorites.contains(sourceId(),current)?"★ Favorite":"☆ Favorite");}
  loading.setVisibility(playbackSession!=null&&playbackSession.isBuffering()?View.VISIBLE:View.GONE);
  renderFullscreen(displayState.mode()==LiveDisplayState.Mode.FULLSCREEN);
  if(displayState.mode()==LiveDisplayState.Mode.BROWSER)channelsView.requestFocus();
 }
 @Override protected void onStart(){super.onStart();if(playbackSession!=null)playbackSession.resumeFromBackground();}
 @Override protected void onStop(){if(playbackSession!=null)playbackSession.pauseForBackground();super.onStop();}
 protected void onDestroy(){super.onDestroy();catalogGeneration++;playbackGeneration++;viewGeneration++;mainUi.removeCallbacksAndMessages(null);epgWorker.shutdownNow();if(playbackSession!=null)playbackSession.release();worker.shutdownNow();imageWorker.shutdownNow();}
